PROTOCOL_VERSION = 1

RECORD_VERSION = 1

MIN_EXECUTABLE = 64

MAX_EXECUTABLE = 256 * 1024 * 1024

MAX_JSON = 64 * 1024

MAX_SIGNATURE = 16 * 1024

RELEASE_TARGETS = (
    "aarch64-apple-darwin",
    "aarch64-unknown-linux-gnu",
    "x86_64-apple-darwin",
    "x86_64-unknown-linux-musl",
