RUNTIME_TARGET = "x86_64-unknown-linux-musl"

OBJECT_PREFIX = "cw/v1"

RELEASE_SCHEMA = "codewire.cw.release/v1"

CHANNEL_SCHEMA = "codewire.cw.channel/v1"

